    msg: str

def test_frozen_exception_attributes():
    exc = MyException("test")

    # These should already work
    exc.__cause__ = Exception("cause")
    exc.__context__ = Exception("context")
    exc.__traceback__ = None

    # These should currently fail but we want them to work
    try:
        exc.__notes__ = "some notes"
        print("__notes__ succeeded")
    except Exception as e:
        print(f"__notes__ failed: {e}")

    try:
        exc.__suppress_context__ = True
        print("__suppress_context__ succeeded")
    except Exception as e:
        print(f"__suppress_context__ failed: {e}")

if __name__ == "__main__":
    test_frozen_exception_attributes()

